package com.company.aiinterview.assessment.controller; import com.company.aiinterview.assessment.dto.request.*; import com.company.aiinterview.assessment.dto.response.*; import com.company.aiinterview.assessment.service.*; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/assessment/interview") @RequiredArgsConstructor public class InterviewController { private final InterviewSessionService interviewSessionService; private final QuestionOrchestrationService questionOrchestrationService; @PostMapping("/start") public StartInterviewResponseDto start(@RequestBody StartInterviewRequestDto request){ return interviewSessionService.startInterview(request);} @GetMapping("/{sessionId}/next-question") public NextQuestionResponseDto next(@PathVariable Long sessionId){ return questionOrchestrationService.getNextQuestion(sessionId);} @PostMapping("/{sessionId}/answer/text") public SubmitAnswerResponseDto submit(@PathVariable Long sessionId,@RequestBody SubmitTextAnswerRequestDto request){ return questionOrchestrationService.submitTextAnswer(sessionId,request);} @PostMapping("/{sessionId}/complete") public void complete(@PathVariable Long sessionId){ interviewSessionService.completeInterview(sessionId);} }
